import{_ as t,o,c as i,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Main-Options.md","filePath":"manual-en/Main-Options.md","lastUpdated":1785684581000}'),n={name:"manual-en/Main-Options.md"};function s(r,e,p,d,l,c){return o(),i("div",null,[...e[0]||(e[0]=[a(`<h3 id="_3-1-main-options" tabindex="-1">3.1 Main Options <a class="header-anchor" href="#_3-1-main-options" aria-label="Permalink to &quot;3.1 Main Options&quot;">​</a></h3><p>Here is a summary of all the options, grouped by type, followed by explanations in the same order.</p><p>In the table, arguments to long options also apply to any corresponding short options.</p><p><em>Non-option arguments</em></p><pre><code>syntax-file
</code></pre><p><em>Output options</em></p><pre><code>-o, --output=output-file
-O option=value
-O format=format
-O device={terminal|listing}
--no-output
--table-look=file
-e, --error-file=error-file
</code></pre><p><em>Language options</em></p><pre><code>-I, --include=dir
-I-, --no-include
-b, --batch
-i, --interactive
-r, --no-statrc
-a, --algorithm={compatible|enhanced}
-x, --syntax={compatible|enhanced}
--syntax-encoding=encoding
</code></pre><p><em>Informational options</em></p><pre><code>-h, --help
-V, --version
</code></pre><p><em>Other options</em></p><pre><code>-s, --safer
--testing-mode
</code></pre><p>syntax-file</p><p>Read and execute the named syntax file. If no syntax files are specified, PSPP prompts for commands. If any syntax files are specified, PSPP by default exits after it runs them, but you may make it prompt for commands by specifying ‘-’ as an additional syntax file.</p><p>-o output-file</p><p>Write output to output-file. PSPP has several different output drivers that support output in various formats (use --help to list the available formats). Specify this option more than once to produce multiple output files, presumably in different formats.</p><p>Use ‘-’ as output-file to write output to standard output.</p><p>If no -o option is used, then PSPP writes text and CSV output to standard output and other kinds of output to whose name is based on the format, <em>e.g.</em> pspp.pdf for PDF output.</p><p>-O option=value</p><p>Sets an option for the output file configured by a preceding -o. Most options are specific to particular output formats. A few options that apply generically are listed below.</p><p>-O format=format</p><p>PSPP uses the extension of the file name given on -o to select an output format. Use this option to override this choice by specifying an alternate format, <em>e.g.</em> -o pspp.out -O format=html to write HTML to a file named pspp.out. Use --help to list the available formats.</p><p>-O device={terminal|listing}</p><p>Sets whether PSPP considers the output device configured by the preceding -o to be a terminal or a listing device. This affects what output will be sent to the device, as configured by the SET command’s output routing subcommands (see <a href="./SET">SET</a>). By default, output written to standard output is considered a terminal device and other output is considered a listing device.</p><p>--no-output</p><p>Disables output entirely, if neither -o nor -O is also used. If one of those options is used, --no-output has no effect.</p><p>--table-look=file</p><p>Reads a table style from file and applies it to all PSPP table output. The file should be a TableLook .stt or .tlo file. PSPP searches for file in the current directory, then in .pspp/looks in the user’s home directory, then in a looks subdirectory inside PSPP’s data directory (usually /usr/local/share/pspp). If PSPP cannot find file under the given name, it also tries adding a .stt extension.</p><p>When this option is not specified, PSPP looks for default.stt using the algorithm above, and otherwise it falls back to a default built-in style.</p><p>Using <code>SET TLOOK</code> in PSPP syntax overrides the style set on the command line (see <a href="./SET">SET</a>).</p><p>-e error-file --error-file=error-file</p><p>Configures a file to receive PSPP error, warning, and note messages in plain text format. Use ‘-’ as error-file to write messages to standard output. The default error file is standard output in the absence of these options, but this is suppressed if an output device writes to standard output (or another terminal), to avoid printing every message twice. Use ‘none’ as error-file to explicitly suppress the default.</p><p>-I dir --include=dir</p><p>Appends dir to the set of directories searched by the <code>INCLUDE</code> (see <a href="./INCLUDE">INCLUDE</a>) and <code>INSERT</code> (see <a href="./INSERT">INSERT</a>) commands.</p><p>-I- --no-include</p><p>Clears all directories from the include path, including directories inserted in the include path by default. The default include path is . (the current directory), followed by .pspp in the user’s home directory, followed by PSPP’s system configuration directory (usually /etc/pspp or /usr/local/etc/pspp).</p><p>-b --batch -i --interactive</p><p>These options forces syntax files to be interpreted in batch mode or interactive mode, respectively, rather than the default “auto” mode. See <a href="./Syntax-Variants">Syntax Variants</a>, for a description of the differences.</p><p>-r --no-statrc</p><p>By default, at startup PSPP searches for a file named rc in the include path (described above) and, if it finds one, runs the commands in it. This option disables this behavior.</p><p>-a {enhanced|compatible} --algorithm={enhanced|compatible}</p><p>With <code>enhanced</code>, the default, PSPP uses the best implemented algorithms for statistical procedures. With <code>compatible</code>, however, PSPP will in some cases use inferior algorithms to produce the same results as the proprietary program SPSS.</p><p>Some commands have subcommands that override this setting on a per command basis.</p><p>-x {enhanced|compatible} --syntax={enhanced|compatible}</p><p>With <code>enhanced</code>, the default, PSPP accepts its own extensions beyond those compatible with the proprietary program SPSS. With <code>compatible</code>, PSPP rejects syntax that uses these extensions.</p><p>--syntax-encoding=encoding</p><p>Specifies encoding as the encoding for syntax files named on the command line. The encoding also becomes the default encoding for other syntax files read during the PSPP session by the <code>INCLUDE</code> and <code>INSERT</code> commands. See <a href="./INSERT">INSERT</a>, for the accepted forms of encoding.</p><p>--help</p><p>Prints a message describing PSPP command-line syntax and the available device formats, then exits.</p><p>-V --version</p><p>Prints a brief message listing PSPP’s version, warranties you don’t have, copying conditions and copyright, and e-mail address for bug reports, then exits.</p><p>-s --safer</p><p>Disables certain unsafe operations. This includes the <code>ERASE</code> and <code>HOST</code> commands, as well as use of pipes as input and output files.</p><p>--testing-mode</p><p>Invoke heuristics to assist with testing PSPP. For use by <code>make check</code> and similar scripts.</p>`,56)])])}const f=t(n,[["render",s]]);export{h as __pageData,f as default};
